  "Modell betöltése": "Loading model",
  "<div class=\"model-loading-card\"><h2>Modell betöltése</h2><p class=\"load-message\" role=\"status\" aria-live=\"polite\"></p><progress class=\"load-progress\" max=\"100\" aria-label=\"Modell betöltése\"></progress><div class=\"load-percent\"></div><p class=\"load-time\"></p><small class=\"load-activity\"></small><p class=\"muted\">A 100% a modellsúlyok betöltését jelzi. Utána még végső előkészítés következhet.</p><div class=\"actions\"><button class=\"load-stop\">Leállítás</button><button class=\"load-close\" hidden>Rendben</button></div></div>": "<div class=\"model-loading-card\"><h2>Loading model</h2><p class=\"load-message\" role=\"status\" aria-live=\"polite\"></p><progress class=\"load-progress\" max=\"100\" aria-label=\"Loading model\"></progress><div class=\"load-percent\"></div><p class=\"load-time\"></p><small class=\"load-activity\"></small><p class=\"muted\">100% means the model weights have loaded. Final preparation may still be needed.</p><div class=\"actions\"><button class=\"load-stop\">Stop</button><button class=\"load-close\" hidden>OK</button></div></div>",
